"""MDP(Markov Decision Process) 정의 파일.

강화학습 문제는 (S, A, R, P, γ) 로 정의되는데, 이 파일이 그중
  S: 관측(상태)을 어떻게 구성할지  → OBSERVATION
  A: 행동을 무엇으로 할지          → SPEED_DELTAS
  R: 보상을 어떻게 줄지            → REWARD
  에피소드 길이/시간 해상도        → SIMULATION
를 결정한다. (전이확률 P는 SUMO 시뮬레이터 자체, γ는 train_config.py의 gamma)

이 파일만 수정하면 sumo_env.py를 건드리지 않고 MDP를 바꿀 수 있다.
"""

# ──────────────────────────────────────────────────────────────
# 1) 시뮬레이션 시간 설정
# ──────────────────────────────────────────────────────────────
SIMULATION = {
    "step_length": 0.5,   # SUMO 1스텝 = 0.5초. RL의 1 timestep과 동일.
                          # 작게 하면(0.1) 제어가 정밀해지지만 에피소드가 길어지고,
                          # 크게 하면(1.0) 학습이 빨라지지만 제어가 거칠어진다.
    "max_steps": 1500,    # 에피소드 최대 스텝 수. 1500 * 0.5초 = 750초.
                          # 학습 지도에 OSM 신호·간선 교차로 신호가 들어가 경로상 신호가 4곳(진연로·연제로·시청·연산)이라
                          # SUMO 기본 운전자도 중앙값 370초(최대 450초) 걸린다. 예전처럼 약 2배 여유 (예전 1000스텝 = 252초의 2배).
                          # 도로 12km를 평균 24 m/s로 달리면 약 1000스텝.
                          # 이 시간 안에 완주 못하면 truncation(시간 초과) 처리.
    "warmup_seconds": (150.0, 300.0),  # OSM 주변 도로망 전용: ego 투입 전
                          # 배경 교통을 이 범위(초) 중 무작위 시간만큼 먼저 흘려서
                          # 도로망 전체에 차가 자연스럽게 퍼지게 한다 (프리필 대신).
    "warmup_steps": 4,    # ego 투입 전 프리필 차량들이 자리잡는 정착 스텝.
                          # (도로 전체를 채우는 일은 road_config의 prefill이
                          #  담당하므로 길게 흘릴 필요가 없다)

    # SUMO GUI 공통 설정 — GUI 확대는 여기 하나만 바꾸면 된다.
    # view_road.py, train/test GUI, 데이터 수집 GUI와 생성되는 highway.gui.xml까지
    # 모두 이 값을 사용한다. 숫자가 클수록 더 가까이 확대된다.
    "gui_zoom": 600.0,    # ego 추적 시 확대 배율(%). SUMO zoom은
                          # "네트워크 전체=100%" 기준이라 도로망이 클수록
                          # 큰 값이 필요. 연산교차로(약 800m) 기준 600% ≈ 시야 130m.
                          # 도로망 크기를 바꾸면 이 값도 비례해 조정할 것.
    "gui_delay": 100.0,
    "gui_view_width": 350.0,  # GUI 대기 화면에서 보여줄 폭(m).
                              # 교차로가 이 폭만큼 확대되어 보인다.
                              # (▶ 재생 후에는 gui_zoom의 ego 추적으로 전환)
    "gui_track_ego": True,

    # 신호 위상 무작위화: reset마다 신호를 주기 중 임의의 시점에서 시작한다.
    # 고정 시작이면 ego가 매번 같은 신호 상태로 교차로에 도착해서
    # "신호를 보는" 대신 "도착 타이밍을 외우는" 정책이 될 수 있다.
    "randomize_signal_phase": True,
    # 워밍업 스냅샷 풀 (OSM 도로망 전용): 워밍업이 끝난 상태를 이 개수만큼
    # 저장해 두고 reset 때 불러 쓴다 (reset이 수 배 빨라짐). 0이면 매번 새로 워밍업.
    # refresh: reset마다 이 확률로 새로 워밍업해서 풀의 상태 하나를 교체.
    "warmup_state_pool": 16,
    "warmup_state_refresh": 0.25,
}

# ──────────────────────────────────────────────────────────────
# 2) 관측 (Observation, 상태 S) — 31차원 (+ 신호 7 + 목표 1 + 상충 2 = 41), 범위 [-1, 1]
#
# "내 차선 + 양옆 2차선씩" 총 5개 차선의 국소 교통 상황을 본다.
# (3차선 도로에서 맨 왼쪽에 있어도 오프셋 -2로 맨 오른쪽 차선까지 보임 —
#  존재하지 않는 오프셋은 연결성 -1 / 밀도 1(꽉 참)으로 인코딩된다)
# 도로 구조(차선 수, 차선 감소 위치 등)에 하드코딩 없이 SUMO 네트워크를
# 실시간 조회하므로, 도로를 바꿔도 관측 코드는 그대로 동작한다.
#
# 레이아웃 (W = visibility, vmax = 제한속도):
#   [0]      내 절대속도 / vmax                                  (0 ~ 1)
#
#   차선별 블록 × 5 (순서: 좌2, 좌1, 현재, 우1, 우2 / k = 0..4)
#   [1+4k]   선행차 상대거리 / W        (0~1,  없으면 1  = "앞이 뻥 뚫림")
#   [2+4k]   선행차 상대속도 / vmax     (-1~1, 없으면 1  = "위협 없음")
#   [3+4k]   후행차 상대거리 / W        (-1~0, 없으면 -1 = "뒤가 뻥 뚫림")
#   [4+4k]   후행차 상대속도 / vmax     (-1~1, 없으면 -1)
#     · 현재 차선 블록은 k=2 → [9..12] (선행거리 = obs[9])
#     · ±2 차선은 SUMO getNeighbors 미지원이라 차선 직접 스캔으로 감지
#     · 상대거리 부호: 선행 +, 후행 -  /  상대속도 = (상대차 속도 - 내 속도)
#     · 상대량이므로 내 절대속도[0]와 조합하면 절대값 복원 가능
#
#   차선 유무 × 5 (같은 순서)  — lane_route_info=False (기본, 프로젝트 공지 반영)
#   [21..25]:
#        -1 : 그 차선이 없음 (내가 맨 왼쪽이면 왼쪽 차선 = -1) 또는 버스전용
#         1 : 차선이 있고 달릴 수 있음
#   (lane_route_info=True면 예전처럼 "그 차선으로 경로를 따라 갈 수 있는 거리 / lane_plan_range"
#    — 차로 단위 경로 안내라서 공지 "세밀한 주행 정보 금지"에 걸림)
#
#   차선별 전방 차량 밀도 × 5 (같은 순서)
#   [26..30]:
#      0~1  : (W 이내 전방 차량 수) / (최대 수용 대수)
#         0 : 텅 빈 차선  ↔  1 : 꽉 찬 차선
#         1 : 차선이 없는 경우도 1 = "꽉 찬 것" 취급 → 자연스럽게 회피 학습
#      · 곧 끊기는 차선은 남은 거리 기준으로 세므로 같은 대수여도 밀도가
#        높게 나온다 ("끊기는 차선에 차가 몰림" 신호)
#
#   다음 신호 교차로의 "진입 도로별" 신호 × 6  (traffic_light["enabled"]일 때)
#   교차로에 들어오는 도로마다 신호가 따로 있으므로 도로 하나 = column 하나.
#   6지 교차로(연산교차로)면 6개 도로가 6개 column을 채운다.
#   값: 1 = 녹색, 0 = 황색, -1 = 적색  (range 안에 신호가 없으면 전부 1)
#   [31]      내 진입 도로 = 내 차로가 받는 신호
#   [32..36]  나머지 진입 도로, 내 도로에서 시계방향 순서
#             (도로가 6개보다 적은 교차로 — 예: 시청 인근 삼거리 — 는 남는 칸이
#              -1. 없는 도로에서는 차가 오지 않으므로 "항상 적색"과 같다)
#   [37]      정지선까지 거리 / range  (0~1, 신호 없으면 1)
#             (remaining_time=True면 [38]에 내 신호가 바뀔 때까지 남은 시간 추가)
#
#   목표 (goal_distance=True일 때)
#   [38]      목표(경로 끝 도로)까지 남은 경로 거리 / 출발 시 경로 거리 (1 → 0)
#
#   큰 틀의 경로 안내 (route_turn["enabled"]일 때, 기본)
#   [39]      다음 교차로(경로가 20° 이상 꺾이는 곳 또는 신호 교차로)에서 꺾는 각도/180
#             (−1 왼쪽 ~ +1 오른쪽, 0 직진; range 안에 없으면 0)
#   [40]      그 교차로까지 거리 / range (없으면 1)
#   (예전 [39..40] 교차로 상충 차량은 프로젝트 공지 "도움 요소 금지"로 기본 끔: junction_foes)
# ──────────────────────────────────────────────────────────────
OBSERVATION = {
    "visibility": 100.0,         # 관측 가능 거리 W (m). 앞뒤 차량 감지와  (2026-11-19 50 → 100: 신호 대기 줄을 보게)
                                 # 상대거리/연결성/밀도 정규화의 기준.
    "internal_lane_obs": True,   # 교차로 내부 연결 차로 위에서도 "곧 들어갈 도로"의 차로 기준으로 관측.
                                 # False(예전)면 교차로 안에서 차로 유무 전부 1, 밀도 전부 0, 옆 차 안 보임
                                 # → 교차로를 지날 때마다 몇 스텝씩 엉뚱한 관측 (사각지대)
    "density_veh_length": 7.5,   # 밀도 계산 시 차량 1대의 점유 길이 (m)
                                 # = 차체(~5m) + 최소 안전간격(~2.5m).
                                 # 최대 수용 대수 = W / 이 값
    # [21..25] 차로 관측: 프로젝트 공지 "어떤 차선으로 주행해야 하는지 등 세밀한 정보 금지"에 따라
    #   기본은 차로가 있는지만 (1 / -1). True면 예전처럼 "그 차로로 경로를 따라 갈 수 있는 거리".
    "lane_route_info": False,
    # 큰 틀의 경로 안내 (내비게이션 "300 m 앞 좌회전"과 같은 수준). 관측 끝에 2칸:
    #   [다음 교차로 회전 각도/180 (-1 왼쪽 ~ +1 오른쪽, 0 직진), 거리/range (없으면 1)]
    #   다음 교차로 = 경로가 min_turn_deg 이상 꺾이는 곳 또는 신호 교차로 중 가장 가까운 곳.
    "route_turn": {"enabled": True, "range": 300.0, "min_turn_deg": 20.0},
    # 차로별 노면 화살표 (5차로 × [좌회전, 직진, 우회전], 갈 수 있으면 1 / 없으면 0 / 차로 없음 -1).
    #   그 차로를 따라 range(m) 안의 첫 신호 교차로 정지선에서 갈 수 있는 방향 = 운전자가 보는 노면 화살표.
    #   내 경로가 어느 차로로 가야 하는지는 알려 주지 않는다 (경로와 무관한 도로 표시).
    #   split=True면 5칸 [왼쪽 l, 약간 왼쪽 L, 직진 s, 약간 오른쪽 R, 오른쪽 r] (6지 교차로처럼 왼쪽이 두 방향인 곳 구분)
    "lane_arrows": {"enabled": True, "range": 150.0, "split": False},
    "lane_plan_range": 100.0,    # 목표 차로 보상(goal_lane_weight)의 정규화 거리 (m).
                                 # "이 차선으로 내 경로를 따라 갈 수 있는 거리"를
                                 # 이 값으로 나눈다. 회전 전 차선변경 여유.
    "traffic_light": {
        "enabled": True,         # False면 31차원 관측 그대로 (예전 모델과 호환)
        "range": 150.0,          # 신호를 감지하는 거리 (m). 정지거리보다 길어야 한다.
        "max_time": 60.0,        # 남은 시간 정규화 기준 (s). 6지 교차로는
                                 # 적색이 길어서(최대 ~130초) 넉넉히 잡는다.
        "approach_columns": 6,   # 진입 도로별 신호 column 수 (6지 교차로 = 6)
        "remaining_time": False, # True면 내 신호 남은 시간 1차원 추가
        "dist_sqrt": True,       # [37] 정지선 거리를 sqrt(거리/range)로 — 정지선 가까이(몇 m) 차이를 구분하게.
                                 # False면 거리/range (예전)
    },
    "goal_distance": True,       # 목표(경로 끝)까지 남은 거리 1차원 추가
    # 교차로 상충 차량: 앞으로 지날 교차로 안에서 내 경로와 엇갈리는 차량.
    # 차로별 앞뒤 차 관측으로는 안 보이는 "옆에서 끼어들어 엇갈리는 차"를 본다.
    # 진행 방향 앞 차체 감지 (센서처럼): SUMO getLeader는 내 경로의 차로만 따라가서, 같은 차로에서 다른 방향
    # 연결 차로로 들어가다 멈춘 차(예: 좌회전 대기)의 뒷부분이 내 앞을 막아도 못 본다. 교차로 안(내부 연결 차로)의
    # 차 중 내 진행 방향 앞 range(m), 내 차폭+margin 안에 들어온 차체가 있으면 현재 차로 앞차 거리를 그쪽으로 고친다.
    # 다른 차의 의도·우선권은 쓰지 않는 물리적 관측. 관측 개수는 그대로 (현재 차로 앞차 [9..10] 값만 바뀜).
    # 2026-11-20 G8, 교통량 0.85, 420회: 충돌 18 → 7 (교차로 안 충돌 12 → 1), 완주 393 → 402.
    "corridor_leader": {"enabled": True, "range": 25.0, "margin": 0.3, "junction_only": True},
    "junction_foes": {
        "enabled": False,        # 끔: 다른 차의 진행 방향(의도)을 이용한 도움 정보라 프로젝트 공지
                                 # ("보조 규칙·도움 요소 금지")에 걸림
        "range": 60.0,           # 상충 지점까지 이 거리(m) 안만 본다 (정규화 기준)
        "time_scale": 5.0,       # 도착 시간차 정규화 (s)
    },
}

# ──────────────────────────────────────────────────────────────
# 3) 행동 (Action, A) — [종방향 가감속, 차선 변경] 2차원
#
# policy가 내는 원시 행동:
#   action[0] = accel ∈ [-1, 1]
#       +1: 최대 가속, 0: 속도 유지, -1: 최대 감속
#
#   action[1] = lane_raw ∈ [-1, 1]
#       환경에서 가장 가까운 {-1, 0, +1}로 양자화해서 실제 차선 명령으로 사용.
#       +1 = 왼쪽 한 차선, 0 = 현재 차선 유지, -1 = 오른쪽 한 차선
#
# PPO는 기존 Gaussian 연속정책을 그대로 유지하고 lane_raw만 환경에서 3값으로
# 양자화한다. 따라서 기존 PPO 구현을 크게 바꾸지 않고 차선변경까지 함께 학습한다.
# 데이터 수집 시에는 raw 행동과 실제 적용된 {-1,0,+1} 명령을 둘 다 저장한다.
# ──────────────────────────────────────────────────────────────
ACTION = {
    # ──────────────────────────────────────────────────
    # 차선변경 안전 게이트 (측면충돌 방지)
    #
    # 변경 명령이 와도 목표 차선의 앞뒤 간격이 아래 조건을 만족하지
    # 않으면 실행하지 않는다 (→ invalid_action_penalty 부과):
    #   앞: gap > min_front_gap + front_tau × 내 속도
    #   뒤: gap > min_rear_gap  + rear_tau  × 후행차 속도
    # 속도 비례 항(tau)은 "빠르게 접근 중인 5m"와 "정지 상태의 5m"의
    # 위험도 차이를 반영한 시간여유 기반 판정이다.
    #
    # 이 게이트가 없으면(안전장치 OFF 환경에서) 무작위 탐험 단계의
    # 차선변경 시도 대부분이 측면충돌 즉사로 이어져, 에이전트가
    # "차선변경 = 죽음"만 학습하고 변경 자체를 포기하는 지역최적에
    # 빠진다. 게이트는 탐험을 살려두되, 종방향(추돌) 위험은 그대로
    # 남겨서 감속/차간유지 학습 신호는 유지한다.
    # ──────────────────────────────────────────────────
    "lane_change_safety": {
        # 끔: 위험한 차로 변경을 대신 막아 주는 규칙은 프로젝트 공지("보조 규칙·도움 요소 금지")에 걸림.
        #   차로가 없는 곳·버스전용차로로는 여전히 못 간다 (물리적 제약). 위험한 변경은 충돌로 배운다.
        "enabled": False,
        # ↓ 공격적 세팅: 최소한의 물리적 여유만 남기고 바짝 파고들기 허용.
        #   (기존 5.0/0.3/0.5/1.0 → 충돌이 다시 늘면 그 값으로 되돌릴 것)
        "min_front_gap": 3.0,   # m
        "min_rear_gap": 3.0,    # m
        "front_tau": 0.15,      # s (내 속도 기준)
        "rear_tau": 0.3,        # s (후행차 속도 기준)
        "approach_horizon": 0.6,  # s. 접근 여유 판정 시간 — "이 시간 안에
                                  # 상대와 만나면 위험". 짧을수록 공격적.
        "spawn_protect": 60.0,  # m. 도로 시작 이 구간 안에서는 변경 금지.
                                # flow가 입구에서 새 차를 만드는데 "생성 직전"
                                # 차량은 관측 불가라 원천 사각지대이기 때문.
    },

    "dim": 2,
    "accel_index": 0,
    "lane_change_index": 1,
    "lane_change_values": (-1, 0, 1),
    "lane_change_threshold": 0.5,   # raw <= -0.5→-1, >=+0.5→+1, 그 사이→0
    "lane_change_duration": 1.0,    # SUMO에 차선 변경 명령을 유지하는 시간(초)
}

# ──────────────────────────────────────────────────────────────
# 4) 보상 (Reward, R)
#
# 매 스텝 보상 = speed_weight * (현재속도 / vmax)          ← 빠를수록 +
#              - close_gap_penalty (간격 < threshold 일 때) ← 위험운전 벌점
# 종료 보상   = -collision_penalty (충돌)  또는  +arrival_bonus (완주)
#
# 설계 의도:
#   속도 보상만 있으면 "무조건 밟는" 정책이 나와 충돌한다.
#   충돌 벌점만 크면 "겁먹고 서 있는" 정책이 나온다.
#   이 둘 사이 균형을 잡는 것이 보상 설계(reward shaping)의 핵심이며,
#   아래 숫자들을 바꿔가며 정책이 어떻게 달라지는지 관찰해보길 권장.
# ──────────────────────────────────────────────────────────────
REWARD = {
    "speed_weight": 0.1,         # 속도 보상 가중치. 한 스텝 최대 +0.1
    "close_gap_threshold": 6.0, # 앞차와 이 거리(m) 미만으로 붙으면 (좁게 따라붙기 허용:
                                 #  10→6m 완화. 추월 직전 대기 위치를 잡기 쉬워짐)
    "close_gap_penalty": 0.1,    #   → 스텝당 이만큼 감점
    "close_gap_min_speed": 1.0,  #   단 내 속도가 이 값(m/s) 미만이면 감점 안 함
                                 #   (신호 대기 줄에 멈춰 있을 때 2~3m 간격은 정상)
    "collision_penalty": 5.0,    # 충돌 시 -5 를 받고 에피소드 즉시 종료
    "arrival_bonus": 2.0,        # 도로 끝까지 완주하면 +2 받고 종료

    # ---- 막힘(blocked) 페널티: 추월 학습의 핵심 신호 ----
    # "느린 앞차에 막혀 있는 상태"에 매 스텝 감점을 준다.
    #   조건: 같은 차선 앞차가 blocked_gap 이내  AND  내 속도가
    #         제한속도 × blocked_speed_frac 미만 (= 막혀서 느린 중)
    # 왜 필요한가: 속도 보상만으로는 "변경의 이득"이 미래에 분산되어
    #   도착하는 데다, 막힘 상태 자체가 드물어(스텝의 ~5%) 학습 신호가
    #   너무 희박하다 (실측: 12업데이트에도 막힘 상태와 일반 상태의
    #   변경확률이 분화되지 않음). 이 페널티는 "유지 = 매 스텝 감점,
    #   변경으로 탈출 = 감점 즉시 중단"이라는 즉각적 차등을 만들어
    #   정확히 그 상태에서 차선변경을 배우게 한다.
    "blocked_penalty": 0.05,     # 막힘 상태 스텝당 감점 (0이면 비활성)
    "blocked_gap": 20.0,         # 앞차가 이 거리(m) 이내면 "막힘" 후보
    "blocked_speed_frac": 0.7,   # 그리고 내 속도 < vmax×이 값일 때만
                                 # (앞이 가까워도 빠르게 흐르면 막힘 아님)

    # ---- 차선변경 관련 (원본 Flow 코드의 lc_penalty / rl_action_penalty 대응) ----
    # ★ 커리큘럼: 두 페널티 모두 초기 학습에서는 0으로 둔다.
    #   실측(run_130630): 페널티 0.05 상태에서 p_lane_change가
    #   0.37→0.11로 단조 붕괴 — 시도의 상당수가 게이트에 막혀 -0.05,
    #   실행돼도 즉시 -0.05인 반면 추월 이득은 지연·분산되어 오므로
    #   "변경 = 손해"만 학습됨. 페널티 없이 추월을 먼저 배우게 하고,
    #   학습 후 지그재그가 과하면 0.02~0.05로 재도입할 것.
    "lane_change_penalty": 0.0,   # 차선변경이 "실행될 때마다" 감점.
                                   #   목적: 이득 없는 지그재그(웨빙) 억제.
                                   #   속도 보상(스텝당 최대 0.1)의 절반 수준이라,
                                   #   "변경해서 더 빨라질 때만 변경"하도록 유도.
                                   #   0으로 두면 자유롭게 바꾸는 정책이 나온다.
    "invalid_action_penalty": 0.0,  # 실행 불가능한 차선변경을 "명령"하면 감점.
                                     #   (맨 왼쪽에서 또 왼쪽, 교차로 내부 등)
                                     #   목적: 의미 없는 행동 출력 자체를 줄여
                                     #   행동 분포를 깔끔하게 만드는 정칙화.

    # ---- 신호 위반 ----
    # 적색 신호에 정지선을 넘으면 감점하고 (기본) 에피소드를 끝낸다.
    # 속도 보상의 합은 "이동 거리"에 비례하므로 신호 대기 자체는 거의
    # 손해가 아니다. 반면 신호 위반은 충돌과 같은 크기로 감점해서
    # "기다리는 것"이 항상 이득이 되도록 한다.
    "red_light_penalty": 5.0,
    # 쓸데없이 멈춤: 속도 < idle_speed, 앞 idle_gap(m) 안에 차 없음, 빨간불 정지선 idle_stopline(m) 안도 아님
    #   → 스텝당 idle_penalty 감점. 0이면 끔.
    "idle_penalty": 0.0,
    "idle_speed": 1.0,
    "idle_gap": 30.0,
    "idle_stopline": 15.0,
    # idle_mode "free": 위 판정 대신 "앞에 비어 있는 거리"(앞차 또는 적·황색 정지선까지, idle_gap까지 봄)에 비례해 감점.
    #   idle_free_min(m) 이내로 붙어 서 있으면 0, 그보다 50 m 이상 비워 두고 서 있으면 idle_penalty.
    "idle_mode": "",
    "idle_free_min": 10.0,
    "red_light_terminate": True,  # True면 위반 즉시 에피소드 종료

    # ---- 목표 도로로 가게 만드는 항 ----
    # ego 경로의 끝 도로(EGO["routes"]의 도착 도로, 예: 중앙대로 동래 방면)가 목표.
    # goal_progress_weight: 이번 스텝에 경로를 따라 목표 쪽으로 간 거리 비례 보상.
    #                       vmax로 달리면 스텝당 이 값. (speed_weight와 비슷한 신호라
    #                       train.py에서 speed_weight 대신 쓴다)
    # goal_lane_weight    : 지금 차로가 목표 도로로 이어지지 않으면 스텝당 감점.
    #                       "이 차로로 경로를 따라 갈 수 있는 거리"가 lane_plan_range
    #                       보다 짧아질수록 커져서, 교차로 앞에서 LANE_RULES상
    #                       목표 도로로 가는 차로에 미리 들어가도록 만든다.
    #                       (어느 차로로 갈지는 정해주지 않고 RL이 고른다)
    # ---- TTC 감점 (충돌 예방) ----
    # 같은 차로 앞차와의 TTC(차간거리 / 접근속도)가 ttc_threshold초 미만이면
    # 스텝당 최대 ttc_penalty 감점. 0이면 비활성.
    "ttc_penalty": 0.0,
    "ttc_threshold": 3.0,
    # ---- 신호 제동 감점 (신호위반 예방) ----
    # 내 신호가 녹색이 아닐 때, 정지선에 서는 데 필요한 감속도 v²/(2·거리)가
    # comfort_decel을 넘으면 초과 비율만큼 스텝당 최대 signal_brake_penalty 감점.
    "signal_brake_penalty": 0.0,
    # ---- 교차로 상충 감점 ----
    # 상충 지점까지 foe_conflict_dist(m) 안이고 도착 시간차 < foe_conflict_threshold(s)면
    # 스텝당 최대 foe_conflict_penalty 감점
    "foe_conflict_penalty": 0.0,
    "foe_conflict_threshold": 2.0,
    "foe_conflict_dist": 30.0,
    "comfort_decel": 3.0,        # m/s². ego 최대 감속 5.0보다 여유 있게
    "goal_progress_weight": 0.0,
    "goal_lane_weight": 0.0,

    # ---- 경로 이탈 ----
    # 내 경로로 이어지지 않는 차선(예: 직진해야 하는데 좌회전 차선) 끝에
    # 2초 이상 멈춰 서면 감점하고 종료한다. 회전 전에 차선을 미리 바꾸도록 유도.
    "wrong_lane_penalty": 5.0,

    # ---- 과속 ----
    # 차로 제한속도를 넘으면 스텝당 overspeed_penalty × (초과 속도 / 제한속도) 감점.
    # 예전에는 행동을 제한속도(50 km/h)에서 잘라 냈는데, 조교 답변(2026-11-23, 14조 4번)에 따라
    # 정책을 강제하는 것이라 없앴다. 0.5면 20% 초과(60 km/h)에 스텝당 −0.1 (목표 진행 보상 최대 +0.1과 비슷).
    "overspeed_penalty": 0.5,

    # ---- 막혀서 실패 (SUMO 순간이동) ----
    # AV가 300초 넘게 못 움직여 SUMO가 순간이동시키면 감점하고 종료한다 (신호위반으로 세지 않음).
    # 감점 크기를 따로 정하려면 "teleport_penalty": 5.0 처럼 넣는다. 없으면 wrong_lane_penalty와 같다.
}
# 보상 스케일에 대한 메모 (수업에서 다뤄볼 만한 지점):
#   처음엔 speed_weight=1.0, collision=-10, arrival=+5 였는데,
#   400스텝 동안 스텝당 +1이 쌓이면 에피소드 리턴이 ~100까지 커진다.
#   그러면 (a) critic이 큰 값을 맞추느라 value_loss가 요동치고,
#          (b) "빨리 달리다 충돌(-10)" 이 "천천히 완주" 보다 이득이 되어
#              충돌 회피를 배울 유인이 약해진다.
#   그래서 속도 보상을 1/10로 줄여 리턴을 ~10 규모로 낮췄다.
#   → 보상의 절대값이 아니라 "항 사이의 상대 비율"이 정책을 결정한다는
#     점을 확인해보는 실험을 해보길 권장.
